import type { Register, ThemeSetArgs } from 'claude-code'

import { makeColors } from './make-colors.js'
import { PALETTE } from './palette'
import { SCENE } from './scene'

// The scene is generated by ../art/gen.mjs (node art/gen.mjs hooks/scene.ts).
const { theme, problems } = makeColors(PALETTE)

const LOOK: ThemeSetArgs = {
  colors: theme,
  backdrop: { scene: 'sky-realm', glass: { blur: 3, opacity: 0.62 } },
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))

    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }
    const set = await $.theme.set(LOOK)

    if (set.isDrawn) {
      $.ui.toast('A wild Slime appears!')
    } else {
      $.ui.status(set.reason)
    }

    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.surface !== 'desktop' && e.surface !== 'mobile') {
      return next(e)
    }

    const { Svg } = $.ui.resolve(e)

    return (
      <Svg
        source={SCENE}
        alt="A pixel-art sky realm: a hero raising an enormous sword beside a blue slime on a floating island, an airship drifting past, and a castle on a floating rock with a waterfall"
        isInteractive
      />
    )
  })
}
